{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "HIGH",
      "explanation": "The S3 bucket lacks an aws_s3_bucket_public_access_block resource, leaving it potentially exposed to public access if misconfigured elsewhere or by default in some regions."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "Ensure that S3 buckets are encrypted with KMS by default",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "MEDIUM",
      "explanation": "Server-side encryption is not explicitly configured. While AWS may apply SSE-S3 by default, best practice and security compliance require explicit configuration of encryption (preferably SSE-KMS) to ensure data at rest is protected."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "Ensure all data stored in the S3 bucket have versioning enabled",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "MEDIUM",
      "explanation": "Versioning is not enabled on the bucket. This prevents recovery from accidental deletions or overwrites, impacting availability and data integrity for the admin dashboard assets."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "LOW",
      "explanation": "Access logging is not configured. Without logs, it is difficult to audit who accessed the admin dashboard files, hindering incident response and security monitoring."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "admin_dashboard" {
  bucket = "smart-city-parking-management-system-s3-admin-dashboard-${random_string.bucket_suffix.result}"
}

resource "aws_s3_bucket_public_access_block" "admin_dashboard" {
  bucket                  = aws_s3_bucket.admin_dashboard.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "admin_dashboard" {
  bucket = aws_s3_bucket.admin_dashboard.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "admin_dashboard" {
  bucket = aws_s3_bucket.admin_dashboard.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_logging" "admin_dashboard" {
  bucket        = aws_s3_bucket.admin_dashboard.id
  target_bucket = aws_s3_bucket.log_bucket.id
  target_prefix = "log/"
}

# Note: The following resources are required for the logging configuration above.
# If 'aws_s3_bucket.log_bucket' does not exist in your state, you must create it 
# or remove the aws_s3_bucket_logging resource to maintain valid Terraform syntax.
resource "aws_s3_bucket" "log_bucket" {
  bucket = "smart-city-parking-management-system-s3-logs-${random_string.bucket_suffix.result}"
}

resource "aws_s3_bucket_public_access_block" "log_bucket" {
  bucket                  = aws_s3_bucket.log_bucket.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}",
  "fix_summary": "Added aws_s3_bucket_public_access_block to prevent public exposure, aws_s3_bucket_server_side_encryption_configuration to enforce KMS encryption, aws_s3_bucket_versioning to enable data protection against deletion/overwrite, and aws_s3_bucket_logging along with a dedicated log bucket to enable audit trails."
}
